/* The SPIR-V -> MSL translator's vertex and fragment stages (section 13):
 * each pair of shaders is translated, compiled by Metal, built into a render
 * pipeline with raw Metal calls, drawn into offscreen textures and compared
 * with a CPU reference. Then malformed and unsupported modules must fail
 * cleanly.
 *
 * Shaders: GLSL in the comment above each array, compiled with
 *   glslangValidator -V --target-env vulkan1.3
 * and *_opt variants additionally with spirv-opt -O. Vulkan's conventions
 * are what the tests check: NDC y = -1 is the top row, FragCoord has its
 * origin at the top left with pixel centers at .5. */
#define PLASMAVK_IMPLEMENTATION
#include "../../plasmavk.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

#include "../pvk_test.h"
#include "../pvk_msl_test.h"
#include "../pvk_msl_render.h"

